"""Batch 10 (EP46-EP50) editorial content. Executed inside epdata.py, so EPS and WP come from there."""
RD10 = "Dibaca 10 Nov 2026"


def _b(rows):
    return {f"s{i+1}": r for i, r in enumerate(rows)}


def _ep(**k):
    k.setdefault("alts", [])
    return k


